def _C_grad_free_conv(h):
    # returns conv and sum for reuse
    c = np.convolve(h, h)
    return c, h.sum()


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    def remaining():
        return deadline - time.process_time()

    # Start point
    if start is not None:
        hs = np.asarray(start, dtype=float).ravel()
        if hs.size > 0 and hs.sum() > 0 and np.all(np.isfinite(hs)):
            best = np.maximum(hs, 0.0)
        else:
            best = np.ones(50)
    else:
        best = np.ones(50)
    bestC = _C(best)

    # Parametrize with a smooth Gaussian-like family and general piecewise-
    # linear profile. Key idea: the optimum is smooth and roughly bell-shaped,
    # so optimize a low-dim parametrization, then refine at high N.

    def eval_profile(N, params):
        x = np.linspace(-1.0, 1.0, N)
        # params: [a1..ak] coefficients of cos(pi*x/2), cos(3pi x/2)...
        # Use even cosine modes -> symmetric bell. Add slight asymmetry term.
        k = len(params) // 2
        z = np.zeros(N)
        for i in range(k):
            z += params[i] * np.cos((2 * i + 1) * 0.5 * np.pi * x)
        # asymmetry via x * cos
        if len(params) > 2 * k:
            z += params[2 * k] * x
        z = z - z.max()
        return np.exp(z)

    # First find good N via test at moderate size
    Ns_to_try = [200, 500, 1000, 2000]

    def obj_at(N):
        def f(p):
            h = eval_profile(N, p)
            s = h.sum()
            if s <= 0:
                return 1e9
            return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)
        return f

    # Coarse search over number of modes and initial coeffs
    best_params = None
    best_N = None
    for N in Ns_to_try:
        if remaining() < 3.0:
            break
        for k in (2, 3, 4):
            if remaining() < 1.5:
                break
            p0 = np.zeros(2 * k + 1)
            p0[0] = 1.0
            p0[1] = 0.3
            try:
                res = minimize(obj_at(N), p0, method='Nelder-Mead',
                               options={'xatol': 1e-6, 'fatol': 1e-10,
                                        'maxiter': 3000, 'maxfev': 6000})
                if best_params is None or res.fun < _C(eval_profile(N, best_params)) if False else True:
                    pass
                h_try = eval_profile(N, res.x)
                c_try = _C(h_try)
                if c_try < bestC:
                    bestC = c_try
                    best_params = res.x.copy()
                    best_N = N
                    best = h_try
            except Exception:
                pass

    # Now refine directly at high N with the discovered mode structure
    for N in (5000, 20000, 30000):
        if best_params is None or remaining() < 2.0:
            break
        p0 = np.zeros(len(best_params))
        # pad/truncate
        m = min(len(p0), len(best_params))
        p0[:m] = best_params[:m]
        try:
            res = minimize(obj_at(N), p0, method='Nelder-Mead',
                           options={'xatol': 1e-7, 'fatol': 1e-12,
                                    'maxiter': 4000, 'maxfev': 8000})
            h_try = eval_profile(N, res.x)
            c_try = _C(h_try)
            if c_try < bestC:
                bestC = c_try
                best_params = res.x.copy()
                best_N = N
                best = h_try
        except Exception:
            pass

    # Final polish: direct coordinate refinement at best_N using a fine
    # multiplicative perturbation on the profile, keeping it smooth.
    if best_params is not None and remaining() > 1.0:
        N = best_N
        p = best_params.copy()
        cur = _C(eval_profile(N, p))
        step = 0.05
        rng = np.random.default_rng(7)
        while remaining() > 0.2:
            idx = rng.integers(0, len(p))
            trial = p.copy()
            trial[idx] += rng.normal() * step
            h_try = eval_profile(N, trial)
            c_try = _C(h_try)
            if c_try < cur:
                p = trial
                cur = c_try
                step = min(step * 1.3, 0.5)
            else:
                step = max(step * 0.97, 1e-5)
        if cur < bestC:
            bestC = cur
            best = eval_profile(N, p)

    # Final: if start was better, return it
    if start is not None:
        hs = np.asarray(start, dtype=float).ravel()
        if hs.size > 0 and hs.sum() > 0 and _C(hs) < bestC:
            return hs

    return best

import numpy as np
import time


def _conv(h):
    n = len(h)
    f = np.fft.rfft(h, 2 * n - 1)
    return np.fft.irfft(f * f, 2 * n - 1)


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * _conv(h).max() / (s * s)


def _grad(h):
    """Gradient of max-convolution w.r.t. h (at argmax), plus value."""
    n = len(h)
    c = _conv(h)
    k = int(np.argmax(c))
    idx = np.arange(n)
    kv = k - idx
    valid = (kv >= 0) & (kv < n)
    g = np.zeros(n)
    g[valid] = 2.0 * h[kv[valid]]
    return c[k], g


def _polish(h, dl, iters=4000, lr0=0.3):
    """Subgradient descent on log-scale to keep positivity."""
    h = np.clip(h, 1e-9, None).astype(float)
    n = len(h)
    best = h.copy()
    bestC = _C(h)
    lr = lr0
    for it in range(iters):
        if time.process_time() > dl:
            break
        s = h.sum()
        # normalize then take gradient (scale-invariant)
        hn = h / s
        _, g = _grad(hn)
        # projected multiplicative step
        step = lr * (1.0 - 0.85 * it / iters)
        h = h * np.exp(-step * g / (np.abs(g).max() + 1e-12))
        h = np.clip(h, 0, None)
        if (it & 15) == 15:
            C = _C(h)
            if C < bestC:
                bestC = C
                best = h.copy()
        if step < 1e-6:
            break
    C = _C(h)
    if C < bestC:
        bestC, best = C, h.copy()
    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    dl = t0 + budget_seconds * 0.80

    def oot():
        return time.process_time() > dl

    best = None
    bestC = np.inf

    if start is not None:
        s0 = np.asarray(start, float)
        if s0.size and s0.sum() > 0 and np.all(np.isfinite(s0)):
            best = np.clip(s0, 0, None).copy()
            bestC = _C(best)

    # Multi-resolution search: smooth bumps at various N, then polish.
    for n in (50, 120, 300, 800, 2000, 5000):
        if oot():
            break
        x = np.linspace(-0.5, 0.5, n)
        inits = [
            np.cos(np.pi * x) ** 2 + 1e-3,
            np.exp(-(x / 0.25) ** 2) + 1e-3,
            np.clip(1 - 2 * np.abs(x), 0, None) + 1e-3,
        ]
        if best is not None:
            # Upsample current best to this n
            xp = np.linspace(0, 1, len(best))
            xi = np.linspace(0, 1, n)
            inits.insert(0, np.interp(xi, xp, best))
        for h0 in inits:
            if oot():
                break
            b, bc = _polish(h0, dl)
            if bc < bestC:
                bestC, best = bc, b

    # Final heavy polish on best.
    if best is not None and not oot():
        for lr in (0.15, 0.05, 0.02):
            if oot():
                break
            b, bc = _polish(best, dl, iters=3000, lr0=lr)
            if bc < bestC:
                bestC, best = bc, b

    if best is None:
        best = np.ones(50)
    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    print("final N", len(best), "C", _C(best))
    return best

