def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _polish(h, deadline):
    """Coordinate descent with multiplicative perturbations and decaying step."""
    h = np.asarray(h, dtype=float).copy()
    cur = _C(h)
    n = len(h)
    step = 0.05
    while step > 1e-5:
        if time.process_time() > deadline:
            break
        improved = False
        for i in range(n):
            if time.process_time() > deadline:
                break
            for mult in (1.0 + step, 1.0 - step):
                trial = h.copy()
                trial[i] *= mult
                c = _C(trial)
                if c < cur - 1e-14:
                    h, cur = trial, c
                    improved = True
                    break
        if not improved:
            step *= 0.5
    return h, cur


def _subgradient_step(h, cur):
    """Reduce the peak of h*h. At peak k: dr/dh[j] = 2(h[k-j]*S - P)/S^3."""
    n = len(h)
    s = h.sum()
    if s <= 0:
        return h, cur
    conv = np.convolve(h, h)
    k = int(np.argmax(conv))
    P = conv[k]
    grad = np.empty(n)
    for j in range(n):
        idx = k - j
        if 0 <= idx < n:
            grad[j] = 2.0 * (h[idx] * s - P)
        else:
            grad[j] = -2.0 * P
    grad /= (s * s * s)
    gnorm = np.sqrt(np.sum(grad * grad))
    if gnorm < 1e-15:
        return h, cur
    lr = 0.5 * s / gnorm
    trial = np.clip(h - lr * grad, 0, None)
    if trial.sum() <= 0:
        return h, cur
    return trial, _C(trial)


