def build_rows(h, knots, N):
    K = len(knots)
    A = np.zeros((K, N + 1))
    for r, k in enumerate(knots):
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx_delta = np.arange(lo, hi + 1)
        idx_h = k - idx_delta
        A[r, idx_delta] = 2.0 * h[idx_h]
        A[r, N] = -1.0
    return A


def slp_active(h0, deadline, out_of_time, max_outer=400):
    h = np.asarray(h0, dtype=float).copy()
    s = h.sum()
    if s <= 0:
        return h, np.inf
    h = h / s
    N = len(h)
    best = h.copy()
    best_c = C_of(h)

    for outer in range(max_outer):
        if out_of_time():
            break
        c = np.convolve(h, h)
        M = c.max()
        W = np.where(c >= 0.995 * M)[0]
        if len(W) == 0:
            W = np.array([int(np.argmax(c))])

        solved = False
        for inner in range(40):
            if out_of_time():
                break
            A_ub = build_rows(h, W, N)
            b_ub = -c[W]

            A_eq = np.zeros((1, N + 1))
            A_eq[0, :N] = 1.0
            b_eq = np.array([0.0])

            bounds = [(0.0, None) for _ in range(N)] + [(None, None)]
            obj = np.zeros(N + 1)
            obj[N] = 1.0

            try:
                res = linprog(obj, A_ub=A_ub, b_ub=b_ub, A_eq=A_eq, b_eq=b_eq,
                              bounds=bounds, method='highs')
            except Exception:
                break
            if not res.success:
                break
            delta = res.x[:N]

            alpha = 1.0
            cur_c = C_of(h)
            improved = False
            trial = None
            tc = None
            for _ in range(25):
                trial = h + alpha * delta
                trial = np.maximum(trial, 0.0)
                ts = trial.sum()
                if ts <= 0:
                    alpha *= 0.5
                    continue
                trial = trial / ts
                tc = C_of(trial)
                if tc < cur_c - 1e-15:
                    improved = True
                    break
                alpha *= 0.5

            if not improved:
                break

            ct = np.convolve(trial, trial)
            tmax = ct.max()
            add = set()
            for k in W:
                if ct[k] > tmax + 1e-12:
                    add.add(int(k))
            near = np.where(ct >= 0.995 * tmax)[0]
            for k in near:
                if k not in W:
                    add.add(int(k))
            h = trial
            if tc < best_c:
                best_c = tc
                best = h.copy()
            if add:
                W = np.array(sorted(set(W.tolist()) | add))
                continue
            else:
                solved = True
                break

        if not solved and out_of_time():
            break
        if out_of_time():
            break

    return best, best_c


def refine(h, deadline, out_of_time):
    h = np.asarray(h, dtype=float).copy()
    cur = C_of(h)
    n = len(h)
    step = 0.01
    while step >= 1e-6 and not out_of_time():
