    h = np.asarray(h, dtype=float)
    N = len(h)
    if N == newN:
        return h.copy()
    x_old = (np.arange(N) + 0.5) / N
    x_new = (np.arange(newN) + 0.5) / newN
    h_new = np.interp(x_new, x_old, h)
    h_new = np.maximum(h_new, 0.0)
    s = h_new.sum()
    if s <= 0:
        return np.ones(newN)
    return h_new / s


def downsample(h, newN):
    """Mass-preserving block averaging."""
    h = np.asarray(h, dtype=float)
    N = len(h)
    if N == newN:
        return h.copy()
    # integrate via cumulative sum at bin edges
    edges = np.linspace(0, N, newN + 1)
    cs = np.concatenate([[0.0], np.cumsum(h)])
    out = np.zeros(newN)
    for i in range(newN):
        a, b = edges[i], edges[i + 1]
        ia, ib = int(np.floor(a)), int(np.ceil(b))
        total = 0.0
        for j in range(ia, min(ib, N)):
            lo = max(a, j)
            hi = min(b, j + 1)
            if hi > lo:
                total += h[j] * (hi - lo)
        out[i] = total / (b - a)
    s = out.sum()
    if s <= 0:
        return np.ones(newN)
    return out / s


